#include <iostream>
#include <cstdio>
#include <cstring>
#include <algorithm>
#include <assert.h>
using namespace std;

/*
p = i * r + x = 0 (% p)
-i * r * inv(x) = 1 (% p)
inv(i) = -r * inv(x) (% p)
*/

const int N = 250010;
long long fac[N], inv[N];
long long dp[30][N];
int bit[N];
long long n, m, mod;

long long com(int n, int m) {
    return fac[n] * inv[n - m] % mod * inv[m] % mod;
}

void add(long long &x, long long y) {
    x += y;
    if (x >= mod) x %= mod;
}

int main()
{
    cin >> n >> m >> mod;   
    inv[0] = fac[0] = inv[1] = fac[1] = 1;
    for (int i = 2; i <= n; i++) {
        int r = mod / i;
        int x = mod - i * r;
        fac[i] = fac[i - 1] * i % mod;
        inv[i] = mod -1LL * r * inv[x] % mod;
    }
    for (int i = 2; i <= n; i++) inv[i] = inv[i - 1] * inv[i] % mod;
    long long ans = 1;
    for (int i = 1; i <= n; i++) ans = ans * m % mod;
    for (int i = 1; i <= n; i++) bit[i] = bit[i >> 1] + (i & 1);
    if (n & 1) {
        cout << ans << endl;
        return 0;
    }
    dp[0][0] = 1;
    for (int i = 0; i < min(0LL + bit[n], m); i++) {
        for (int j = 0; j < n; j++) {
            if (!dp[i][j]) continue;
            int x = n ^ j;
            for (int k = x, r; k > j; k = (k - 1) & x) {
                r = k | j;
                add(dp[i + 1][r], dp[i][j] * inv[k]); 
            }
        }
    }
    for (int i = 1; i <= m; i++) 
        ans -= dp[i][n] * fac[m] % mod * inv[m - i] % mod * fac[n] % mod;
    ans = (mod + ans % mod) % mod;
    cout << ans << endl;
    return 0;
}

